.si-anim svg { overflow: visible; }

/* =====================================================================
   BATCH 1: Icons 1-20
   ===================================================================== */

/* 1. MENU: 3D book-open. Folds open on Y axis like opening a book. */
.si-icon-cell:hover .khey6q svg,
.icon-card:hover .khey6q svg {
  animation: cr96dy 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: left center;
  filter: drop-shadow(0 0 4px rgba(96, 165, 250, 0.3));
}

/* 2. CLOSE: Brightness flash + 90 snap. Screen goes white then X appears. */
.si-icon-cell:hover .l1wizt svg,
.icon-card:hover .l1wizt svg {
  animation: lemm97 0.4s ease forwards;
  transform-origin: center;
}

/* 3. ARROW-BACK: Motion blur slide. Streaks left with directional blur. */
.si-icon-cell:hover .ex7c3d svg,
.icon-card:hover .ex7c3d svg {
  animation: aaxhzt 0.45s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* 4. ARROW-FORWARD: Motion blur slide right. Mirror of arrow-back. */
.si-icon-cell:hover .dyst9j svg,
.icon-card:hover .dyst9j svg {
  animation: c0xfyq 0.45s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* 5. CHEVRON-LEFT: Wall bounce. Hits left wall, squashes, rebounds. */
.si-icon-cell:hover .yrneby svg,
.icon-card:hover .yrneby svg {
  animation: tcecph 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: left center;
}

/* 6. CHEVRON-RIGHT: Wall bounce right. Mirror of chevron-left. */
.si-icon-cell:hover .s58udc svg,
.icon-card:hover .s58udc svg {
  animation: k2wlgq 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: right center;
}

/* 7. EXPAND-MORE: Gravity drop. Falls with realistic gravity ease. */
.si-icon-cell:hover .hfiyhc svg,
.icon-card:hover .hfiyhc svg {
  animation: cf6cr6 0.5s cubic-bezier(0.55, 0.06, 0.68, 0.19) forwards;
  transform-origin: center top;
}

/* 8. EXPAND-LESS: Helium rise. Floats up like a balloon. */
.si-icon-cell:hover .ag2h8k svg,
.icon-card:hover .ag2h8k svg {
  animation: xkruzg 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center bottom;
}

/* 9. HOME: Heartbeat. Two quick warm pulses like arriving home. */
.si-icon-cell:hover .gm68u1 svg,
.icon-card:hover .gm68u1 svg {
  animation: nzw19p 0.6s ease forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 5px rgba(34, 197, 94, 0.3));
}

/* 10. SEARCH: Orbit scan. Traces a circular search pattern. */
.si-icon-cell:hover .rtj91l svg,
.icon-card:hover .rtj91l svg {
  animation: jkgevt 0.7s ease forwards;
  transform-origin: 60% 60%;
  filter: drop-shadow(0 0 5px rgba(251, 191, 36, 0.35));
}

/* 11. SETTINGS: Notch clicks. Rotates in discrete 20-degree steps. */
.si-icon-cell:hover .phslsv svg,
.icon-card:hover .phslsv svg {
  animation: kvs8s1 0.65s steps(3, end) forwards;
  transform-origin: center;
}

/* 12. MORE-VERT: Domino cascade. Tilts through a wave top-to-bottom. */
.si-icon-cell:hover .mfm1dp svg,
.icon-card:hover .mfm1dp svg {
  animation: y46cue 0.55s ease forwards;
  transform-origin: center top;
}

/* 13. MORE-HORIZ: Squeeze-stretch. Horizontal rubber-band snap. */
.si-icon-cell:hover .h70r96 svg,
.icon-card:hover .h70r96 svg {
  animation: z55l6b 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 14. APPS: Per-dot staggered pulsation (9 individual dots). */
.si-icon-cell:hover .neg10d svg,
.icon-card:hover .neg10d svg {
  filter: drop-shadow(0 0 5px rgba(139, 92, 246, 0.3));
}
.si-icon-cell:hover .neg10d .nm-dot-5,
.icon-card:hover .neg10d .nm-dot-5 {
  animation: usi85j 0.7s ease both;
  transform-origin: 480px -480px;
  animation-delay: 0s;
}
.si-icon-cell:hover .neg10d .nm-dot-1,
.icon-card:hover .neg10d .nm-dot-1 {
  animation: dvafrz 0.65s ease both;
  transform-origin: 240px -720px;
  animation-delay: 0.06s;
}
.si-icon-cell:hover .neg10d .nm-dot-8,
.icon-card:hover .neg10d .nm-dot-8 {
  animation: r1oudt 0.6s ease both;
  transform-origin: 480px -240px;
  animation-delay: 0.12s;
}
.si-icon-cell:hover .neg10d .nm-dot-3,
.icon-card:hover .neg10d .nm-dot-3 {
  animation: usi85j 0.7s ease both;
  transform-origin: 720px -720px;
  animation-delay: 0.17s;
}
.si-icon-cell:hover .neg10d .nm-dot-7,
.icon-card:hover .neg10d .nm-dot-7 {
  animation: dvafrz 0.65s ease both;
  transform-origin: 240px -240px;
  animation-delay: 0.22s;
}
.si-icon-cell:hover .neg10d .nm-dot-2,
.icon-card:hover .neg10d .nm-dot-2 {
  animation: r1oudt 0.6s ease both;
  transform-origin: 480px -720px;
  animation-delay: 0.27s;
}
.si-icon-cell:hover .neg10d .nm-dot-6,
.icon-card:hover .neg10d .nm-dot-6 {
  animation: usi85j 0.7s ease both;
  transform-origin: 720px -480px;
  animation-delay: 0.32s;
}
.si-icon-cell:hover .neg10d .nm-dot-9,
.icon-card:hover .neg10d .nm-dot-9 {
  animation: dvafrz 0.65s ease both;
  transform-origin: 720px -240px;
  animation-delay: 0.37s;
}
.si-icon-cell:hover .neg10d .nm-dot-4,
.icon-card:hover .neg10d .nm-dot-4 {
  animation: r1oudt 0.6s ease both;
  transform-origin: 240px -480px;
