}

/* 15. FULLSCREEN: 3D depth punch. Zooms toward viewer in Z-space. */
.si-icon-cell:hover .t1hflu svg,
.icon-card:hover .t1hflu svg {
  animation: ehml87 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 16. FILTER-LIST: Tightening funnel. Narrows progressively. */
.si-icon-cell:hover .yvi8by svg,
.icon-card:hover .yvi8by svg {
  animation: us9zfm 0.55s ease forwards;
  transform-origin: center top;
  filter: drop-shadow(0 0 4px rgba(249, 115, 22, 0.3));
}

/* 17. SORT: 3D card flip. Full rotation on X axis. */
.si-icon-cell:hover .yo5jm6 svg,
.icon-card:hover .yo5jm6 svg {
  animation: gdame4 0.5s ease forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 4px rgba(249, 115, 22, 0.3));
}

/* 18. REFRESH: Full 360 spin with mid-pause "catch". */
.si-icon-cell:hover .ii46oc svg,
.icon-card:hover .ii46oc svg {
  animation: jh2llx 0.7s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 5px rgba(34, 197, 94, 0.35));
}

/* 19. TAB: Peel-up. Lifts corner like peeling a sticky note. */
.si-icon-cell:hover .teizag svg,
.icon-card:hover .teizag svg {
  animation: qhwh3n 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: bottom left;
}

/* 20. DRAG-INDICATOR: Levitate. Lifts off surface with growing shadow. */
.si-icon-cell:hover .trbgb4 svg,
.icon-card:hover .trbgb4 svg {
  animation: debbkc 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* =====================================================================
   BATCH 2: Icons 21-50
   ===================================================================== */

/* 21. ARROW-UPWARD: Rocket ignition. Crouches down then blasts up. */
.si-icon-cell:hover .qg3z4c svg,
.icon-card:hover .qg3z4c svg {
  animation: wba47p 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* 22. ARROW-DOWNWARD: Parachute descent. Floats down with gentle sway. */
.si-icon-cell:hover .px7jp4 svg,
.icon-card:hover .px7jp4 svg {
  animation: wizphe 0.7s ease forwards;
}

/* 23. SWAP-VERT: Seesaw. Pivots on center like a playground seesaw. */
.si-icon-cell:hover .zhk6p1 svg,
.icon-card:hover .zhk6p1 svg {
  animation: ynqrwp 0.6s ease forwards;
  transform-origin: center;
}

/* 24. SWAP-HORIZ: Pendulum. Swings left-right like a metronome. */
.si-icon-cell:hover .p2yasg svg,
.icon-card:hover .p2yasg svg {
  animation: mkbecx 0.65s ease forwards;
  transform-origin: center top;
}

/* 25. UNDO: Rewind whirl. Counter-clockwise arc with blur. */
.si-icon-cell:hover .uvw8ga svg,
.icon-card:hover .uvw8ga svg {
  animation: o2hfaz 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 26. REDO: Fast-forward whirl. Clockwise arc with blur. */
.si-icon-cell:hover .yu91ki svg,
.icon-card:hover .yu91ki svg {
  animation: rgvrj7 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 27. MENU-OPEN: Door swing. Opens on left hinge like a door. */
.si-icon-cell:hover .pan1ky svg,
.icon-card:hover .pan1ky svg {
  animation: zql5ne 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: left center;
}

/* 28. SEGMENT: Venetian blind tilt. Slats rotate open. */
.si-icon-cell:hover .x8kchj svg,
.icon-card:hover .x8kchj svg {
  animation: nbndxd 0.55s ease forwards;
  transform-origin: left center;
}

/* 29. DENSITY-MEDIUM: Spring compress. Squashes then over-extends. */
.si-icon-cell:hover .cjzxal svg,
.icon-card:hover .cjzxal svg {
  animation: uelnl2 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 30. VIEW-SIDEBAR: Drawer slide. Translates from off-screen left. */
.si-icon-cell:hover .vc4fg9 svg,
.icon-card:hover .vc4fg9 svg {
  animation: lr6rab 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* 31. DOCK-TO-RIGHT: Magnetic snap right with velocity blur. */
.si-icon-cell:hover .i3gudr svg,
.icon-card:hover .i3gudr svg {
  animation: r1vfpj 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* 32. DOCK-TO-LEFT: Magnetic snap left with velocity blur. */
.si-icon-cell:hover .i8na7x svg,
.icon-card:hover .i8na7x svg {
  animation: fluw9s 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* 33. GRID-VIEW: Kaleidoscope twist. Quick rotational burst. */
.si-icon-cell:hover .erdfu1 svg,
.icon-card:hover .erdfu1 svg {
  animation: f4iuwc 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 5px rgba(34, 211, 238, 0.3));
}

/* 34. VIEW-LIST: Typewriter slide-in with stutter stops. */
.si-icon-cell:hover .y48i6f svg,
.icon-card:hover .y48i6f svg {
  animation: ox3msm 0.6s steps(4, end) forwards;
  transform-origin: left center;
}

/* 35. VIEW-MODULE: 3D coin flip on Y axis. */
.si-icon-cell:hover .pbq25z svg,
.icon-card:hover .pbq25z svg {
  animation: c13nz6 0.5s ease forwards;
  transform-origin: center;
}

/* 36. DASHBOARD: Jelly wobble. Squash-stretch with overshoot. */
.si-icon-cell:hover .s8k5f9 svg,
.icon-card:hover .s8k5f9 svg {
  animation: iml6to 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center bottom;
}

/* 37. SPLITSCREEN: Zipper open. Stretches apart vertically. */
.si-icon-cell:hover .ytw97b svg,
.icon-card:hover .ytw97b svg {
  animation: lugfg2 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 38. PIP: Shrink-drift. Shrinks and floats to bottom-right corner. */
.si-icon-cell:hover .kaxzpz svg,
.icon-card:hover .kaxzpz svg {
  animation: pt6zuo 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: bottom right;
}

/* 39. OPEN-IN-NEW: Diagonal catapult with trail fade. */
.si-icon-cell:hover .b8a6pk svg,
.icon-card:hover .b8a6pk svg {
  animation: je7re9 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* 40. LAUNCH: Liftoff with exhaust glow. Rises with brightness burst. */
.si-icon-cell:hover .qhhgp5 svg,
.icon-card:hover .qhhgp5 svg {
  animation: nob0j6 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* 41. ZOOM-IN: Lens iris bloom. Brightens and slightly enlarges. */
.si-icon-cell:hover .rzoaek svg,
.icon-card:hover .rzoaek svg {
  animation: hjx7fm 0.5s ease forwards;
  transform-origin: 40% 40%;
}

/* 42. ZOOM-OUT: Lens iris dim. Dims and slightly contracts. */
.si-icon-cell:hover .pc1lka svg,
.icon-card:hover .pc1lka svg {
  animation: ylpzol 0.5s ease forwards;
  transform-origin: 40% 40%;
}

/* 43. FIRST-PAGE: Book slam left. Whips to start with impact. */
.si-icon-cell:hover .h52sei svg,
.icon-card:hover .h52sei svg {
  animation: lj1ycd 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* 44. LAST-PAGE: Book slam right. Whips to end with impact. */
.si-icon-cell:hover .y9ve0j svg,
.icon-card:hover .y9ve0j svg {
  animation: pg94h3 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* 45. UNFOLD-MORE: Origami bloom. Grows vertically with 3D depth. */
.si-icon-cell:hover .rsme7l svg,
.icon-card:hover .rsme7l svg {
  animation: dtb44r 0.55s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 46. UNFOLD-LESS: Origami crush. Compresses with 3D depth. */
.si-icon-cell:hover .pxd7xb svg,
.icon-card:hover .pxd7xb svg {
  animation: liepoc 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 47. OPEN-IN-FULL: Supernova burst. Rapid expansion with glow. */
.si-icon-cell:hover .tgs1m9 svg,
.icon-card:hover .tgs1m9 svg {
  animation: mamiki 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 48. CLOSE-FULLSCREEN: Black hole collapse. Rapid contraction with dim. */
.si-icon-cell:hover .xztak0 svg,
.icon-card:hover .xztak0 svg {
  animation: plnkxp 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 49. DOUBLE-ARROW: Speed demon. Stretches tall and blurs upward. */
.si-icon-cell:hover .bvjfy0 svg,
.icon-card:hover .bvjfy0 svg {
  animation: iz1v0h 0.45s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* 50. SUBDIRECTORY: L-path waterfall. Flows down then sweeps right. */
.si-icon-cell:hover .iifsex svg,
.icon-card:hover .iifsex svg {
  animation: hzqdrk 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* ===================================================================
   KEYFRAMES - Each uses a fundamentally different motion type
   =================================================================== */

/* ---- BATCH 1 KEYFRAMES ---- */

/* 1. Book open: 3D perspective fold */
@keyframes cr96dy {
  0%   { transform: perspective(200px) rotateY(0deg); }
  45%  { transform: perspective(200px) rotateY(-35deg); }
  75%  { transform: perspective(200px) rotateY(8deg); }
  100% { transform: perspective(200px) rotateY(0deg); }
}

/* 2. Flash snap: brightness burst + rotation */
@keyframes lemm97 {
  0%   { transform: rotate(0deg); filter: brightness(1) drop-shadow(0 0 0 transparent); }
  25%  { transform: rotate(45deg); filter: brightness(2) drop-shadow(0 0 8px rgba(239,68,68,0.5)); }
  50%  { transform: rotate(90deg); filter: brightness(1.5) drop-shadow(0 0 4px rgba(239,68,68,0.3)); }
  75%  { transform: rotate(88deg); filter: brightness(1) drop-shadow(0 0 2px rgba(239,68,68,0.15)); }
  100% { transform: rotate(0deg); filter: brightness(1) drop-shadow(0 0 0 transparent); }
}

/* 3. Motion blur left */
@keyframes aaxhzt {
  0%   { transform: translateX(0); filter: blur(0) drop-shadow(0 0 0 transparent); }
  30%  { transform: translateX(-10px); filter: blur(2px) drop-shadow(0 0 4px rgba(96,165,250,0.3)); }
  60%  { transform: translateX(-12px); filter: blur(0) drop-shadow(0 0 2px rgba(96,165,250,0.2)); }
  80%  { transform: translateX(2px); filter: blur(0) drop-shadow(0 0 0 transparent); }
  100% { transform: translateX(0); filter: blur(0) drop-shadow(0 0 0 transparent); }
}

/* 4. Motion blur right */
@keyframes c0xfyq {
  0%   { transform: translateX(0); filter: blur(0) drop-shadow(0 0 0 transparent); }
  30%  { transform: translateX(10px); filter: blur(2px) drop-shadow(0 0 4px rgba(96,165,250,0.3)); }
  60%  { transform: translateX(12px); filter: blur(0) drop-shadow(0 0 2px rgba(96,165,250,0.2)); }
  80%  { transform: translateX(-2px); filter: blur(0) drop-shadow(0 0 0 transparent); }
  100% { transform: translateX(0); filter: blur(0) drop-shadow(0 0 0 transparent); }
}

/* 5. Wall bounce left: hits and squashes */
@keyframes tcecph {
  0%   { transform: translateX(0) scaleX(1); }
  25%  { transform: translateX(-8px) scaleX(1); }
  40%  { transform: translateX(-9px) scaleX(0.7) scaleY(1.15); }
  55%  { transform: translateX(-4px) scaleX(1.1) scaleY(0.95); }
  75%  { transform: translateX(2px) scaleX(1); }
  100% { transform: translateX(0) scaleX(1); }
}

/* 6. Wall bounce right */
@keyframes k2wlgq {
  0%   { transform: translateX(0) scaleX(1); }
  25%  { transform: translateX(8px) scaleX(1); }
  40%  { transform: translateX(9px) scaleX(0.7) scaleY(1.15); }
  55%  { transform: translateX(4px) scaleX(1.1) scaleY(0.95); }
  75%  { transform: translateX(-2px) scaleX(1); }
  100% { transform: translateX(0) scaleX(1); }
}

/* 7. Gravity fall: accelerating downward with slight rotation */
@keyframes cf6cr6 {
  0%   { transform: translateY(0) rotate(0deg); filter: drop-shadow(0 0 0 transparent); }
  20%  { transform: translateY(1px) rotate(0deg); }
  50%  { transform: translateY(6px) rotate(3deg); }
  70%  { transform: translateY(10px) rotate(5deg); filter: drop-shadow(0 0 4px rgba(96,165,250,0.3)); }
  85%  { transform: translateY(-2px) rotate(-1deg); }
  100% { transform: translateY(0) rotate(0deg); filter: drop-shadow(0 0 0 transparent); }
}

/* 8. Helium rise: gentle float upward with wobble */
@keyframes xkruzg {
  0%   { transform: translateY(0) rotate(0deg); opacity: 1; }
  20%  { transform: translateY(-2px) rotate(-2deg); }
  40%  { transform: translateY(-7px) rotate(3deg); opacity: 0.85; }
  60%  { transform: translateY(-10px) rotate(-2deg); opacity: 0.75; }
  80%  { transform: translateY(-3px) rotate(1deg); opacity: 0.9; }
  100% { transform: translateY(0) rotate(0deg); opacity: 1; }
}

/* 9. Heartbeat: two quick scale pulses */
@keyframes nzw19p {
  0%   { transform: scale(1); }
  14%  { transform: scale(1.2); }
  24%  { transform: scale(1); }
  36%  { transform: scale(1.15); }
  48%  { transform: scale(0.95); }
  65%  { transform: scale(1.02); }
  100% { transform: scale(1); }
}

/* 10. Orbit scan: traces a small circle */
@keyframes jkgevt {
  0%   { transform: translate(0, 0) rotate(0deg); }
  15%  { transform: translate(4px, -3px) rotate(-8deg); }
  30%  { transform: translate(6px, 1px) rotate(-15deg); }
  50%  { transform: translate(3px, 5px) rotate(-22deg); }
  70%  { transform: translate(-2px, 3px) rotate(-12deg); }
  85%  { transform: translate(-3px, -1px) rotate(-5deg); }
  100% { transform: translate(0, 0) rotate(0deg); }
}

/* 11. Notch clicks: stepped rotation */
@keyframes kvs8s1 {
  0%   { transform: rotate(0deg); filter: drop-shadow(0 0 0 transparent); }
  33%  { transform: rotate(20deg); filter: drop-shadow(0 0 3px rgba(148,163,184,0.3)); }
  66%  { transform: rotate(40deg); filter: drop-shadow(0 0 4px rgba(148,163,184,0.4)); }
  100% { transform: rotate(60deg); filter: drop-shadow(0 0 2px rgba(148,163,184,0.2)); }
}

/* 12. Domino cascade: perspective tilt forward */
@keyframes y46cue {
  0%   { transform: perspective(150px) rotateX(0deg); }
  35%  { transform: perspective(150px) rotateX(25deg); }
  55%  { transform: perspective(150px) rotateX(-10deg); }
  75%  { transform: perspective(150px) rotateX(5deg); }
  100% { transform: perspective(150px) rotateX(0deg); }
}

/* 13. Rubber band: horizontal squeeze-stretch */
@keyframes z55l6b {
  0%   { transform: scaleX(1) scaleY(1); }
  20%  { transform: scaleX(1.3) scaleY(0.8); }
  40%  { transform: scaleX(0.8) scaleY(1.2); }
  60%  { transform: scaleX(1.15) scaleY(0.9); }
  80%  { transform: scaleX(0.95) scaleY(1.04); }
  100% { transform: scaleX(1) scaleY(1); }
}

/* 14a-c. Apps dot pulse variants */
@keyframes usi85j {
  0%   { transform: scale(1); opacity: 1; }
  30%  { transform: scale(1.45); opacity: 0.6; }
  55%  { transform: scale(0.85); opacity: 1; }
  75%  { transform: scale(1.1); opacity: 0.9; }
  100% { transform: scale(1); opacity: 1; }
}
@keyframes dvafrz {
  0%   { transform: scale(1) rotate(0deg); opacity: 1; }
